      expect(screen.getByText(/crown jewels/i)).toBeInTheDocument();
      await user.click(screen.getByRole('button', { name: /place order/i }));

      // Confirmation
      await waitFor(() => {
        expect(screen.getByText(/ord-1066/i)).toBeInTheDocument();
      });
      expect(onComplete).toHaveBeenCalledWith('ORD-1066');
    });
  });

